import{_ as o,l as n,o as e,c as i,v as p,p as m,x as l,d as r,i as d,S as h,b as t}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"状态空间对偶 SSD","description":"","frontmatter":{"title":"状态空间对偶 SSD","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/state-space-duality.md","filePath":"llm/state-space-duality.md","lastUpdated":1789023840000}'),S={name:"llm/state-space-duality.md"};function E(c,a,_,f,u,M){const s=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=p('<h1 id="状态空间对偶-ssd" tabindex="-1">状态空间对偶 SSD <a class="header-anchor" href="#状态空间对偶-ssd" aria-label="Permalink to &quot;状态空间对偶 SSD&quot;">​</a></h1><div class="epigraph"><p>一类对角 SSM 与一类结构化掩码注意力写出同一个二次型；扫描和分块 GEMM 是同一层的两种算法。</p><footer>—— Dao &amp; Gu, Transformers are SSMs: Generalized Models and Efficient Algorithms Through Duality, 2024</footer></div><p><a href="/llm/chunked-parallel-form">上一课</a>给了扫描的分块并行。<a href="/llm/linear-attention">线性注意力</a> 给了核特征下的矩阵形式。<a href="/llm/mamba">Mamba</a> 与注意力在实现上长期分家。本课补状态空间对偶（SSD）：在对角、选择满足一定结构时，<strong>SSM 扫描与一种带结构掩码的注意力在数学上等价</strong>，从而训练可以用分块矩阵乘，推理可以用循环。Mamba-2 建在这条对偶上。后课 GLA 把门再加回去，默认你会「线性注意力 \\(\\Leftrightarrow\\) 某种 SSM」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>课序里已经有两条线性时间路线：核化注意力先乘 \\(K,V\\) 成状态；SSM 先按 \\(A,B\\) 更新再读 \\(C\\)。实现、初始化、论文词汇都不通。缺口是一张对应表：何时 \\(y=\\mathrm{scan}(A,B,C;x)\\) 能写成 \\(y=\\mathrm{mask}(QK^\\top)V\\) 的结构化特例，从而复用注意力侧已经打磨的 GEMM 与分块核。</p><p>对偶不是「softmax Transformer 等于 S4」。Softmax 非线性打破对偶。对象是线性（或对角加门在扫描外）的那一族。</p><p><span class="marginnote"><a href="/llm/mamba-2">Mamba-2</a> 若已读，本课是补层里把对偶写成可引用定义，不把型号当课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对角 SSM 每通道 \\(h_t=\\alpha_t h_{t-1}+b_t x_t\\)，\\(y_t=c_t h_t\\)。展开</p> \\[y_t=\\sum_{s\\le t}\\Big(\\prod_{k=s+1}^{t}\\alpha_k\\Big) c_t b_s x_s. \\]<p>右边是下三角权重 \\(M_{ts}=\\big(\\prod_{k=s+1}^{t}\\alpha_k\\big) c_t b_s\\) 乘 \\(x\\)。令查询、键吸收 \\(c,b\\) 与 \\(\\alpha\\) 的前缀积，则 \\(M\\) 来自某种 \\(QK^\\top\\) 再逐点乘一个只依赖距离与选择的结构（或被吸收进 \\(Q,K\\) 的累积）。于是前向可走：构造 \\(Q,K,V\\) 后做<strong>分块掩码乘法</strong>，等价于分块扫描。</p><p>算法选择：短块、高状态维时 GEMM 更香；长依赖、状态在 SRAM 里时扫描更香。对偶允许同一层在两种核之间切换，而不是两套模型。</p><h3 id="对偶破坏项" tabindex="-1">对偶破坏项 <a class="header-anchor" href="#对偶破坏项" aria-label="Permalink to &quot;对偶破坏项&quot;">​</a></h3><p>行 softmax、头间耦合的稠密 \\(A\\)、扫描内部的非线性门，都会让 \\(M\\) 不能写成上述低结构。这些项要么移到扫描外（如输出门），要么放弃 SSD 核走通用扫描。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前缀积 \\(\\prod\\alpha\\) 扮演因果掩码加衰减位置编码的角色：离当前越远且中间 \\(\\alpha\\) 越小，贡献越弱。选择 \\(\\alpha_t(x_t)\\) 时，衰减变成内容相关，对应「结构化的、输入依赖的注意力矩阵」，但仍是 rank 受状态维约束的矩阵，不是满秩 softmax。</p><p>这解释了线性模型的召回上限：等价注意力矩阵的秩或生成元宽度被 \\(N\\) 限制，无法表达任意稀疏的单点检索。后课会用基准打这条。</p><p><span class="marginnote">对偶是算法身份，不是容量身份。说「Mamba-2 是 Transformer」若指 SSD 核，可以；若指 softmax 表达力，不可以。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对偶给出高效核，不自动给出更好的语言建模。把已有 softmax 模型的权重解释成 SSM 通道，一般做不到。混合架构仍要在层上显式选择走哪一种核。下一课 GLA 在线性注意力一侧加数据依赖门，对偶仍可能成立，但门的位置必须落在扫描外或对角结构内。</p>',20)),(e(),m(h,null,{default:l(()=>[d(s,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20SSM%5B%22%E5%AF%B9%E8%A7%92%E9%80%89%E6%8B%A9%E6%80%A7%20SSM%22%5D%20--%3E%20Expand%5B%22%E5%B1%95%E5%BC%80%E6%88%90%E4%B8%8B%E4%B8%89%E8%A7%92%20M%22%5D%0A%20%20Attn%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E7%BA%BF%E6%80%A7%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%20--%3E%20Expand%0A%20%20Expand%20--%3E%20Gemm%5B%22%E5%88%86%E5%9D%97%20GEMM%22%5D%0A%20%20Expand%20--%3E%20Scan%5B%22%E5%88%86%E5%9D%97%E6%89%AB%E6%8F%8F%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t("h2",{id:"小结",tabindex:"-1"},[r("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=t("ul",null,[t("li",null,"SSD：对角（选择）SSM 与结构化线性注意力展开为同一下三角作用，训练 GEMM、推理扫描可互换。"),t("li",null,"Softmax 与扫描内非线性不在对偶里。"),t("li",null,"等价注意力矩阵受状态维约束，精确召回仍有上限。"),t("li",null,"对偶是核与身份，不是把 Transformer 检查点改写成 Mamba。"),t("li",null,"出处：Dao & Gu, 2024。")],-1))])}const B=o(S,[["render",E]]);export{x as __pageData,B as default};
